<template>
  <main class="page my-coupons-page">
    <header class="topbar wallet-topbar"><button class="icon-button" aria-label="返回" @click="router.back()"><AppIcon name="arrow-left" /></button><h1>我的优惠券</h1><RouterLink to="/coupons" class="claim-top">去领券 <AppIcon name="chevron-right" size="14" /></RouterLink></header>
    <div class="wallet-content">
      <section class="wallet-intro"><span class="intro-icon"><AppIcon name="ticket" size="25" /></span><div><h2>已领取的优惠券</h2><p v-if="wallet">当前可用 <b>{{wallet.usableCount}}</b> 张 · 每笔订单限用一张</p><p v-else>查看已领优惠券与使用记录</p></div><button class="refresh" aria-label="刷新优惠券" :disabled="loading" @click="load"><AppIcon name="refresh" size="18" /></button></section>
      <nav class="coupon-tabs" aria-label="优惠券状态"><button v-for="tab in couponTabs" :key="tab.key" :class="{active:activeTab===tab.key}" :aria-current="activeTab===tab.key?'page':undefined" @click="switchTab(tab.key)">{{tab.label}}<span v-if="wallet">{{wallet[tab.countKey]}}</span></button></nav>
      <section v-if="error" class="wallet-error" role="alert"><AppIcon name="info" size="19" /><p>{{error}}</p><button @click="load">重试</button></section>
      <p v-if="loading&&!wallet" class="loading-state">优惠券加载中…</p>
      <section v-else-if="wallet&&!items.length" class="wallet-empty"><span><AppIcon name="ticket" size="32" /></span><h3>{{emptyText}}</h3><p>领取、使用和退款后的券状态会展示在这里</p><RouterLink to="/coupons">去优惠券中心看看 <AppIcon name="chevron-right" size="15" /></RouterLink></section>
      <section v-for="item in items" :key="item.userCouponId" class="owned-coupon" :class="{muted:item.group!=='UNUSED'}" :data-state="item.state">
        <div class="coupon-face"><div class="coupon-value"><strong>{{item.coupon ? couponValue(item.coupon) : '—'}}</strong><small>{{item.coupon ? couponThreshold(item.coupon) : '信息不可用'}}</small></div><div class="coupon-copy"><div class="coupon-title"><h2>{{item.coupon?.name || '优惠券信息已失效'}}</h2><span class="state-badge" :class="item.state.toLowerCase()">{{item.stateLabel}}</span></div><p>{{item.coupon ? couponScope(item.coupon) : item.reason}}</p><small v-if="item.coupon">有效期 {{formatCouponTime(item.coupon.useStartsAt || item.coupon.startsAt)}}<br />至 {{formatCouponTime(item.coupon.useEndsAt || item.coupon.endsAt)}}</small></div></div>
        <p class="coupon-reason" v-if="item.state!=='AVAILABLE'"><AppIcon :name="item.state==='LOCKED'?'clock':'info'" size="14" />{{item.reason}}</p>
        <details v-if="item.coupon" class="coupon-rules"><summary>使用规则 <AppIcon name="chevron-right" size="13" /></summary><div><p>{{couponScope(item.coupon)}}；每笔订单限用一张。</p><p v-if="item.coupon.couponType==='DISCOUNT'">{{couponCapLabel(item.coupon)}}。</p><p>{{couponLimitLabel(item.coupon)}}。</p><p>优惠后最低实付 ¥{{item.coupon.minPayAmount ?? '0.01'}}。</p><p>{{item.coupon.refundPolicy==='NO_RETURN'?'退款成功后不返还优惠券。':'退款成功后，未过期且仍有效的优惠券退回，原有效期不变。'}}</p><p v-if="item.coupon.description">{{item.coupon.description}}</p><p>领取时间：{{formatCouponTime(item.claimedAt)}}</p><p v-if="item.usedAt">使用时间：{{formatCouponTime(item.usedAt)}}</p></div></details>
        <footer class="coupon-footer" v-if="item.state==='AVAILABLE'||item.orderId"><small v-if="item.orderNo" class="order-no">关联订单 {{item.orderNo}}</small><small v-else-if="item.state==='AVAILABLE'">具体抵扣金额以确认订单为准</small><RouterLink v-if="item.state==='AVAILABLE'&&item.coupon" class="use-coupon" :to="couponDestination(item.coupon)">去使用</RouterLink><RouterLink v-else-if="item.state==='LOCKED'&&item.canPay" class="use-coupon" :to="`/orders/pay/${item.orderId}`">继续支付</RouterLink><RouterLink v-else-if="item.orderId" class="view-order" :to="`/orders/${item.orderId}`">查看订单 <AppIcon name="chevron-right" size="14" /></RouterLink></footer>
      </section>
      <p class="wallet-note" v-if="wallet&&items.length">优惠券状态以当前账号的实际领取、订单及退款记录为准</p>
    </div>
  </main>
</template>
<script setup>
import {computed,ref,watch,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import AppIcon from '../../components/AppIcon.vue'
import {couponApi} from '../../api/coupon'
import {couponValue,couponThreshold,couponScope,couponCapLabel,couponLimitLabel} from '../../utils/couponForm'
import {couponTabs,couponDestination,formatCouponTime} from '../../utils/couponWallet'
const route=useRoute(),router=useRouter(),wallet=ref(null),loading=ref(true),error=ref(''),activeTab=ref('unused')
const items=computed(()=>wallet.value?.items?.filter(item=>item.group===activeTab.value.toUpperCase()) || [])
const emptyText=computed(()=>({unused:'暂无未使用优惠券',used:'暂无优惠券使用记录',invalid:'暂无已失效优惠券'}[activeTab.value]))
let request=0,poll
watch(()=>route.query.tab,value=>{activeTab.value=couponTabs.some(t=>t.key===value)?value:'unused'},{immediate:true})
function switchTab(key){router.replace({path:'/coupons/mine',query:{tab:key}})}
async function load(silent=false){silent=silent===true;const current=++request,token=sessionStorage.getItem('city-veri-tick-token');if(!silent)loading.value=true;error.value='';try{const data=await couponApi.mine();if(current===request&&token===sessionStorage.getItem('city-veri-tick-token'))wallet.value=data}catch(e){if(current===request)error.value=e.message||'优惠券加载失败，请稍后重试'}finally{if(current===request)loading.value=false}}
function visible(){if(document.visibilityState==='visible')load(true)}
onMounted(()=>{load();document.addEventListener('visibilitychange',visible);poll=setInterval(()=>{if(document.visibilityState!=='hidden')load(true)},60000)})
onUnmounted(()=>{request++;clearInterval(poll);document.removeEventListener('visibilitychange',visible)})
</script>
<style scoped>
