-wrap:anywhere}.coupon-value small{display:block;font-size:11px;color:#7b8ba5;margin-top:5px;line-height:1.5}.coupon-copy{min-width:0;flex:1}.coupon-title{display:flex;align-items:flex-start;gap:7px;justify-content:space-between}.coupon-title h2{margin:0;font-size:15px;line-height:1.5;overflow-wrap:anywhere}.state-badge{border-radius:5px;background:#eef2f7;color:#8d9ab0;font-size:10px;padding:3px 5px;white-space:nowrap;flex:none;line-height:1.4}.state-badge.available{color:#2463eb;background:#edf3ff}.state-badge.not_started{color:#a87823;background:#fff6e3}.state-badge.locked{color:#d17824;background:#fff2e8}.coupon-copy p{font-size:11px;margin:7px 0;line-height:1.6;color:#7a8aa5;overflow-wrap:anywhere}.coupon-copy>small{font-size:10px;line-height:1.6;color:#95a1b5}.coupon-reason{display:flex;align-items:flex-start;gap:5px;font-size:11px;color:#9b865e;background:#fffbf2;padding:9px 13px;margin:0 14px 12px;border-radius:7px;line-height:1.5}.coupon-reason .app-icon{flex:none;margin-top:1px}.muted .coupon-value strong{color:#9aabc1}.muted .coupon-reason{background:#f5f7fa;color:#8c99ab}.coupon-rules{padding:0 15px}.coupon-rules summary{list-style:none;display:flex;align-items:center;gap:4px;font-size:11px;color:#8292aa;padding:10px 0;border-top:1px dashed #e6ecf5;cursor:pointer}.coupon-rules summary::-webkit-details-marker{display:none}.coupon-rules[open] summary .app-icon{transform:rotate(90deg)}.coupon-rules>div{background:#f8faff;padding:9px 10px;border-radius:8px;margin-bottom:12px}.coupon-rules p{font-size:11px;color:#8190a7;line-height:1.6;margin:4px 0}.coupon-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 15px;border-top:1px solid #edf1f7;min-height:53px}.coupon-footer>small{min-width:0;flex:1;font-size:10px;color:#99a6ba;line-height:1.5}.order-no{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.use-coupon{background:#2463eb;color:#fff;border-radius:16px;padding:8px 15px;font-size:12px;flex:none}.view-order{display:inline-flex;align-items:center;color:#8192ac;font-size:12px;white-space:nowrap}.wallet-note{text-align:center;color:#a6b0c0;font-size:10px;line-height:1.7;margin:22px 4px}.wallet-empty{text-align:center;background:#fff;border:1px solid #e5ebf4;border-radius:15px;padding:42px 16px}.wallet-empty>span{display:grid;place-items:center;width:65px;height:65px;margin:auto;background:#f0f4ff;border-radius:50%;color:#9eb6e9}.wallet-empty h3{font-size:16px;margin:19px 0 10px}.wallet-empty p{font-size:12px;color:#95a3b8;line-height:1.6}.wallet-empty a{display:inline-flex;align-items:center;gap:3px;font-size:12px;color:#2463eb;background:#edf3ff;border-radius:17px;padding:10px 14px;margin-top:12px}.wallet-error{display:flex;align-items:center;gap:8px;background:#fff0f2;color:#bc5263;padding:12px;border-radius:10px;font-size:12px;margin-bottom:16px}.wallet-error p{margin:0;flex:1;min-width:0;line-height:1.6}.wallet-error button{background:none;border:0;color:#2463eb;font-size:12px;white-space:nowrap}.loading-state{text-align:center;color:#8d9db4;padding:36px 0;font-size:13px}@media(max-width:350px){.wallet-content{padding:0 12px}.coupon-face{padding:16px 12px;gap:10px}.coupon-value{width:68px}.coupon-title{flex-wrap:wrap}.wallet-intro h2{font-size:16px}.wallet-intro p{font-size:11px}}
</style>
